inputs = ['fiz', 'ee', 'ifwuw', 'cvf', 'zgvze']
outputs = ['fizg', 'ee', 'ifwuw', 'cvf', 'eyvzge']

# Find what actually changed
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input: '{inp}' -> Output: '{out}'")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_positions.append((j, inp[j], out[j]))

        # Check if it's just appending
        if len(out) > len(inp) and inp == out[:len(inp)]:
            print(f"  Appended: '{out[len(inp):]}'")
        elif len(inp) > len(out) and out == inp[:len(out)]:
            print(f"  Truncated: removed '{inp[len(out):]}'")
        else:
            print(f"  Differences at positions: {diff_positions}")
            if len(out) > len(inp):
                print(f"  Appended: '{out[len(inp):]}'")
            elif len(inp) > len(out):
                print(f"  Removed: '{inp[len(out):]}'")
    else:
        print("  No change")
    print()

